insert into public.questions (id, stage, question_type, stem, explanation, subject_id, difficulty, marks, estimated_seconds, is_free_sample, origin, status) values ('54a78c1c-d189-527a-873c-64ad9c3579e3', 'PE', 'mcq', 'Under the Constitution, Bhutan''s Parliament consists of the Druk Gyalpo and which two houses?', 'Article 10 of the Constitution provides that Parliament consists of the Druk Gyalpo, the National Council and the National Assembly. The Cabinet (Lhengye Zhungtshog) is the executive, and the Supreme Court is part of the judiciary.', (select id from public.subjects where stage = 'PE' and slug = 'general-awareness-current-affairs'), 'standard', 1, 60, true, 'original', 'awaiting_review') on conflict (id) do nothing;
insert into public.question_options (id, question_id, label, body, is_correct, position) values ('c83631d6-6aa6-576a-9abd-5278b92ab47d', '54a78c1c-d189-527a-873c-64ad9c3579e3', 'A', 'The National Council and the National Assembly', true, 1) on conflict (id) do nothing;
