insert into public.questions (id, stage, question_type, stem, explanation, subject_id, difficulty, marks, estimated_seconds, is_free_sample, origin, status) values ('d4a68303-1646-5d40-a1f0-003a0820eb43', 'PE', 'mcq', 'Bhutan''s currency, the Ngultrum, is pegged at par to which currency?', 'The Ngultrum is pegged one-to-one to the Indian rupee, which is also widely accepted in Bhutan.', (select id from public.subjects where stage = 'PE' and slug = 'general-awareness-current-affairs'), 'foundation', 1, 60, true, 'original', 'awaiting_review') on conflict (id) do nothing;
