insert into public.questions (id, stage, question_type, stem, model_answer, word_limit, subject_id, difficulty, marks, origin, status) values ('7a483648-2926-5196-9ccd-411bec7c988a', 'ME', 'short_answer', 'In about 150 words, explain the purpose of the Preliminary Examination (PE) in the Bhutan Civil Service Examination, and explain why PE marks are not carried forward to the Main Examination.', 'The Preliminary Examination is the first stage of the BCSE. Its purpose is to shortlist candidates for the Main Examination and to ensure that every candidate meets a minimum standard. It is common to all categories of graduates and uses objective questions to test English and Dzongkha communication skills, logic and problem-solving, data interpretation, and general awareness and current affairs.
